WITH matched_keys AS (SELECT city, country FROM suppliers EXCEPT ALL SELECT city, country FROM suppliers WHERE supplier_name NOT LIKE '%EuroG%'), verified AS (SELECT s.* FROM suppliers s INNER JOIN matched_keys k ON s.city = k.city AND s.country = k.country) SELECT country, STDDEV_SAMP(rating) AS rating_stddev, COUNT(*) FILTER (WHERE city = 'London') AS london_rows, SUM(rating) FILTER (WHERE city = 'Chiang Mai') AS chiang_mai_total_rating, STDDEV_SAMP(rating) AS rating_stddev_2, STDDEV_SAMP(rating) AS rating_stddev_3, ROUND(AVG(rating), 2) AS avg_rating FROM verified GROUP BY 1 ORDER BY london_rows DESC NULLS LAST;
